cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
};

struct VSIn {
    [[vk::location(0)]] float3 pos : POSITION;
    [[vk::location(1)]] float3 nrm : NORMAL;
    [[vk::location(2)]] float2 uv  : TEXCOORD0;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 nrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv  : TEXCOORD1;
};

float4x4 lookAtRH(float3 eye, float3 at, float3 up)
{
    float3 zaxis = normalize(eye - at);
    float3 xaxis = normalize(cross(up, zaxis));
    float3 yaxis = cross(zaxis, xaxis);
    return float4x4(
        float4(xaxis, -dot(xaxis, eye)),
        float4(yaxis, -dot(yaxis, eye)),
        float4(zaxis, -dot(zaxis, eye)),
        float4(0, 0, 0, 1)
    );
}

float4x4 perspectiveRH(float fovY, float aspect, float zn, float zf)
{
    float f = 1.0f / tan(fovY * 0.5f);
    return float4x4(
        float4(f / aspect, 0, 0, 0),
        float4(0, f, 0, 0),
        float4(0, 0, zf / (zn - zf), (zn * zf) / (zn - zf)),
        float4(0, 0, -1, 0)
    );
}

VSOut VSMain(VSIn i)
{
    VSOut o;

    float2 m = float2(mouse_x / max(1.0f, resolution_x), mouse_y / max(1.0f, resolution_y));
    float yaw = (m.x - 0.5f) * 6.2831853f;
    float pitch = (0.5f - m.y) * 1.45f;
    float dist = max(0.5f, 3.0f - 0.35f * scroll_delta_y);

    float3 at = float3(0, 0, 0);
    float3 eye = float3(
        dist * cos(pitch) * sin(yaw),
        dist * sin(pitch),
        dist * cos(pitch) * cos(yaw)
    );

    float4x4 V = lookAtRH(eye, at, float3(0, 1, 0));
    float aspect = max(0.001f, resolution_x / max(1.0f, resolution_y));
    float4x4 P = perspectiveRH(radians(60.0f), aspect, 0.05f, 100.0f);

    float4 wp = float4(i.pos, 1.0f);
    o.pos = mul(P, mul(V, wp));
    o.nrm = normalize(i.nrm);
    o.uv = i.uv;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 nrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv  : TEXCOORD1;
};

float4 PSMain(VSOut i) : SV_Target
{
    float3 n = normalize(i.nrm);
    float3 l = normalize(float3(0.5, 0.7, 0.2));
    float ndl = max(dot(n, l), 0.0);
    float3 base = float3(i.uv, 0.6);
    float3 col = base * (0.2 + 0.8 * ndl);
    return float4(col, 1.0);
}
